'use strict';
const ICONS={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',dumbbell:'m7 7 10 10M3 6l3-3 3 3-3 3zm12 12 3-3 3 3-3 3zM2 9l7-7m6 20 7-7',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',chart:'M3 3v18h18M7 14l4-4 4 3 5-8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-6v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2Z',activity:'M2 12h4l3-9 6 18 3-9h4',leaf:'M20 3C7 2 2 9 5 16s17 4 15-13Zm-1 1L5 20',drop:'M12 2C10 6 5 11 5 15a7 7 0 0 0 14 0c0-4-5-9-7-13Z',moon:'M21 13A9 9 0 0 1 11 3 9 9 0 1 0 21 13Z',wind:'M3 8h12a3 3 0 1 0-3-3M2 12h17a3 3 0 1 1-3 3M4 17h5a3 3 0 1 1-3 3',walk:'M14 4a2 2 0 1 0 0 .1ZM7 12l3-4 4 1 3 5h4M10 8l-1 8-4 5m5-7 5 3 1 5',food:'M4 2v7m3-7v7m3-7v7M4 7h6l-3 4v11m11-20c-3 3-3 7 0 10v10m0-20v10h3V2',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z',search:'M17 17l5 5M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Z m-5 9 3 3 6-6',play:'m8 4 12 8-12 8Z',pause:'M7 4v16m10-16v16',skip:'m4 5 10 7-10 7Zm14 0v14',plus:'M12 4v16M4 12h16',minus:'M4 12h16',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',trash:'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7m4-7v7',edit:'m16 3 5 5-12 12-6 1 1-6Z M13 6l5 5',info:'M12 10v7m0-11v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',external:'M14 3h7v7m0-7-11 11M10 3H3v18h18v-7',sound:'M3 9h4l5-5v16l-5-5H3Zm13-2a8 8 0 0 1 0 10m3-13a12 12 0 0 1 0 16',mute:'M3 9h4l5-5v16l-5-5H3Zm13 0 6 6m0-6-6 6',zoom:'M17 17l5 5M19 10a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM10 6v8m-4-4h8',repeat:'m17 2 4 4-4 4M3 10V6h18M7 22l-4-4 4-4m14 0v4H3',book:'M12 5c-4-3-8-2-10-1v16c4-2 7-2 10 0 3-2 6-2 10 0V4c-3-2-7-2-10 1Zm0 0v15',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[name]||ICONS.activity}"/></svg>`;}
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>dateKey(new Date());
function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
const parseDate=s=>new Date(s+'T12:00:00');
const niceDate=(s,opts={day:'numeric',month:'short'})=>parseDate(s).toLocaleDateString('es-ES',opts);
const validDate=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(parseDate(s).getTime())&&dateKey(parseDate(s))===s;
const num=(v,min,max,def=0)=>Number.isFinite(Number(v))?Math.max(min,Math.min(max,Number(v))):def;
function uid(){return globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);}
const STORE='casa_activa_v1@'+new URL('./',document.baseURI).pathname;
function initial(){return {version:1,profile:{name:'',minutes:25,rest:45,sound:false,goal:3},favorites:[],habits:{},logs:[],weights:[],plan:['base-a','bike','rest','base-b','elliptical','mobility','rest'],active:null};}
let storageOK=true,storageMessage='',S=initial();
// Solo se importan campos esperados; se limita tamaño y se descarta HTML ejecutable.
function sanitize(raw){
 if(!raw||raw.version!==1||!Array.isArray(raw.logs)||!Array.isArray(raw.weights))throw Error('Formato no reconocido. Usa una copia de CASA ACTIVA v1.');
 const d=initial(),p=raw.profile||{};d.profile={name:String(p.name||'').slice(0,40),minutes:[15,25,35].includes(+p.minutes)?+p.minutes:25,rest:num(p.rest,30,180,45),sound:p.sound===true,goal:num(p.goal,1,7,3)};
 d.favorites=Array.isArray(raw.favorites)?[...new Set(raw.favorites.filter(x=>typeof x==='string'&&Object.hasOwn(EX,x)))]:[];
 d.plan=Array.isArray(raw.plan)&&raw.plan.length===7?raw.plan.map(x=>x==='rest'||Object.hasOwn(ROUTINE,x)?x:'rest'):d.plan;
 d.logs=raw.logs.slice(-3000).filter(l=>l&&validDate(l.date)&&l.date<=today()&&Number.isFinite(+l.minutes)&&+l.minutes>0).map(l=>({id:String(l.id||uid()).slice(0,90),date:l.date,title:String(l.title||'Entrenamiento').slice(0,100),minutes:num(l.minutes,1,600),cardio:num(l.cardio,0,num(l.minutes,1,600)),strength:l.strength===true,note:String(l.note||'').slice(0,500),effort:num(l.effort,1,10,5),partial:l.partial===true}));
 d.weights=raw.weights.slice(-2000).filter(w=>w&&validDate(w.date)&&w.date<=today()&&Number.isFinite(+w.kg)&&+w.kg>=25&&+w.kg<=350).map(w=>({date:w.date,kg:Math.round(+w.kg*10)/10}));
 d.weights=[...new Map(d.weights.map(w=>[w.date,w])).values()].sort((a,b)=>a.date.localeCompare(b.date));
 if(raw.habits&&typeof raw.habits==='object')for(const [key,val] of Object.entries(raw.habits).slice(-2000))if(validDate(key)&&key<=today()&&val&&typeof val==='object')d.habits[key]=Object.fromEntries(HABITS.map(h=>[h.id,val[h.id]===true]));
 // Las sesiones en curso solo se recuperan si todas sus etapas son válidas.
 if(raw.active&&Object.hasOwn(ROUTINE,raw.active.routine)&&Array.isArray(raw.active.steps)&&raw.active.steps.length>0&&raw.active.steps.length<200){
  let a=raw.active,steps=a.steps.filter(st=>st&&['warm','cool','rest','strength','cardio','mobility'].includes(st.kind)&&(!st.ex||Object.hasOwn(EX,st.ex))).map(st=>({kind:st.kind,title:String(st.title||'Ejercicio').slice(0,100),ex:st.ex||null,secs:st.secs===null?null:num(st.secs,5,5400,45),hint:String(st.hint||'').slice(0,500),round:num(st.round,1,3,1)}));
  if(steps.length===a.steps.length){d.active={id:String(a.id||uid()).slice(0,90),routine:a.routine,steps,index:Math.floor(num(a.index,0,steps.length-1)),elapsed:num(a.elapsed,0,3600000),total:num(a.total,0,36000000),cardio:num(a.cardio,0,36000000),done:Array.isArray(a.done)?[...new Set(a.done.filter(x=>Number.isInteger(x)&&x>=0&&x<steps.length))]:[],skipped:Array.isArray(a.skipped)?[...new Set(a.skipped.filter(x=>Number.isInteger(x)&&x>=0&&x<steps.length))]:[],running:false,last:null,date:validDate(a.date)?a.date:today()};}
 }
 return d;
}
try{localStorage.setItem(STORE+'_test','1');localStorage.removeItem(STORE+'_test');const raw=localStorage.getItem(STORE);if(raw)S=sanitize(JSON.parse(raw));}catch(e){if(e instanceof SyntaxError||String(e.message).includes('Formato')){storageMessage='No se pudo leer el guardado anterior. No lo sobrescribas sin conservar una copia.';storageOK=false;}else{storageOK=false;storageMessage='El navegador no permite el guardado local en este contexto. Puedes usar la app, pero exporta tu progreso antes de cerrar.';}}
let page='home',routineFilter='all',exerciseFilter='all',query='',favOnly=false,modalMode='',selectedRoutine=null,poseInterval=null,toastTimeout,clockInterval,lastDay=today(),audioCtx=null;
function save(){if(!storageOK)return false;try{localStorage.setItem(STORE,JSON.stringify(S));return true;}catch(e){storageOK=false;storageMessage='No se ha podido guardar. Exporta una copia antes de salir.';updateStorageBadge();toast(storageMessage);return false;}}
function updateStorageBadge(){const el=$('#storage');if(el)el.innerHTML=`<span class="status-dot" style="${storageOK?'':'background:#B88240'}"></span><span class="status-label">${storageOK?'Guardado local':'Sin guardado'}</span>`;}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('show'),4200);}
function sourceLink(key,text){const s=SOURCES[key]||SOURCES.strength;return `<a class="source-link" href="${s.url}" target="_blank" rel="noopener noreferrer">${icon('external')}${esc(text||s.name)}</a>`;}
function weekDays(){const now=new Date();const mon=new Date(now);mon.setDate(now.getDate()-((now.getDay()+6)%7));return Array.from({length:7},(_,i)=>{let d=new Date(mon);d.setDate(mon.getDate()+i);return dateKey(d);});}
function weekStats(){const keys=weekDays(),logs=S.logs.filter(l=>keys.includes(l.date));return {logs,minutes:logs.reduce((n,l)=>n+l.minutes,0),cardio:logs.reduce((n,l)=>n+l.cardio,0),strength:new Set(logs.filter(l=>l.strength).map(l=>l.date)).size,days:new Set(logs.map(l=>l.date)).size};}
function roundsFor(r,mins=S.profile.minutes){return r.id==='express'?1:mins===15?1:mins===25?2:3;}
function duration(r,rounds=roundsFor(r),mins=S.profile.minutes){if(r.kind==='cardio')return mins;if(r.kind==='mobility')return 15;const n=r.ex.length*rounds;return Math.ceil((480+n*45+(n-1)*S.profile.rest)/60);}
function timeChoices(action='minutes',current=S.profile.minutes){return `<div class="segmented" aria-label="Tiempo disponible">${[15,25,35].map(x=>`<button type="button" data-action="${action}" data-id="${x}" class="${current===x?'selected':''}" aria-pressed="${current===x}">${x} min</button>`).join('')}</div>`;}
function statCards(){const st=weekStats();return `<div class="stats-row">${[['check',st.logs.length,'Sesiones esta semana',''],['clock',Math.round(st.minutes),'Minutos de sesión','min'],['dumbbell',st.strength,'Días con fuerza','días'],['activity',Math.round(st.cardio),'Cardio moderado','min']].map(([i,n,t,u])=>`<div class="card stat"><div class="icon-wrap">${icon(i)}</div><div><strong>${n}<em>${u}</em></strong><small>${t}</small></div></div>`).join('')}</div>`;}
function weekStrip(){const names=['L','M','X','J','V','S','D'];return `<div class="week-strip">${weekDays().map((key,i)=>{let done=S.logs.some(l=>l.date===key);return `<div class="day ${key===today()?'today':''} ${done?'done':''} ${S.plan[i]!=='rest'?'planned':''}" aria-label="${niceDate(key,{weekday:'long',day:'numeric',month:'long'})}${done?', actividad registrada':''}"><span>${names[i]}</span><strong>${done?icon('check'):parseDate(key).getDate()}</strong><span class="day-dot"></span></div>`;}).join('')}</div>`;}
function routineCard(r){return `<button class="card routine-card" data-action="routine" data-id="${r.id}" aria-label="Ver rutina ${r.name}"><div class="routine-art ${r.color}"><span class="pill">${r.tag}</span>${scene(r.cover,1,false)}</div><div class="routine-info"><div class="eyebrow">${r.subtitle}</div><h3>${r.name}</h3><p>${r.equipment}</p><div class="routine-bottom"><span>${icon('clock')} ${r.kind==='strength'?'≈':''}${duration(r)} min · ${r.ex.length} ${r.kind==='cardio'?'máquina'+(r.ex.length>1?'s':''):'ejercicios'}</span><span class="round-arrow">${icon('arrow')}</span></div></div></button>`;}
function exerciseCard(e){const fav=S.favorites.includes(e.id);return `<article class="card exercise-card"><button class="fav-btn ${fav?'on':''}" data-action="favorite" data-id="${e.id}" aria-label="${fav?'Quitar de':'Añadir a'} favoritos: ${e.name}" aria-pressed="${fav}">${icon('star')}</button><button class="open-ex" data-action="exercise" data-id="${e.id}" aria-label="Ver técnica de ${e.name}"><div class="picture">${scene(e.id,1,false)}<span class="visual-kind ${hasRealisticImage(e.id)?'':'sketch'}">${hasRealisticImage(e.id)?'Ilustración realista · IA':'Esquema'}</span></div><div class="exercise-card-info"><h3>${e.name}</h3><p>${e.muscles}</p><div class="exercise-card-footer"><span class="pill">${EQUIPMENT[e.equipment]}</span><span class="round-arrow">${icon('arrow')}</span></div></div></button></article>`;}
function empty(title,text,button=''){return `<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${text}</p>${button}</div>`;}
function footer(){return `<footer class="footer"><span>CASA ACTIVA · Tu espacio para moverte mejor.</span><div class="row"><button data-action="sources">Fuentes y seguridad</button><span>·</span><button data-action="privacy">Privacidad</button><span>v1.2 · PWA</span></div></footer>`;}
function pageHeader(label,title,desc,action=''){return `<div class="page-header"><div><div class="eyebrow">${label}</div><h1 tabindex="-1" id="page-title">${title}</h1><p>${desc}</p></div>${action}</div>`;}
function resumeBanner(){if(!S.active)return '';return `<div class="resume-banner"><span>${icon('pause')} <strong>Tienes una sesión en curso</strong><br>${esc(ROUTINE[S.active.routine].name)}</span><button class="btn btn-primary" data-action="resume">Continuar ${icon('arrow')}</button></div>`;}
function homeHTML(){const st=weekStats(),todayPlan=S.plan[(new Date().getDay()+6)%7],r=ROUTINE[S.logs.length?(todayPlan==='rest'?'mobility':todayPlan):'base-a'];const name=S.profile.name?`, ${esc(S.profile.name)}`:'';
 return pageHeader('Un poco cada día',`Tu casa. Tu ritmo${name}.`,'Entrena, cuídate y construye hábitos que se queden.',`<span class="pill">${icon('leaf')} Sin prisas. Sin extremos.</span>`)+resumeBanner()+`<div class="dashboard-grid"><section class="hero"><div class="hero-copy"><div class="eyebrow">${S.logs.length?'Tu propuesta de hoy':'Tu siguiente pequeño paso'}</div><h2>${r.name}</h2><p>${r.kind==='mobility'?'Hoy también puedes elegir descansar.':'Una sesión guiada, con el material que ya tienes en casa.'}</p><div class="hero-meta"><span>${icon('clock')} ${r.kind==='strength'?'≈':''}${duration(r)} min</span><span>${icon('dumbbell')} ${r.ex.length} ejercicios</span></div><button class="btn btn-lime" data-action="routine" data-id="${r.id}">${icon('play')} Preparar entrenamiento</button></div><div class="hero-art">${scene(r.cover,1,false)}<div class="hero-float">${icon('check')} A tu ritmo, con control</div></div></section><section class="card week-card"><div class="row between"><h3>Tu semana, paso a paso</h3>${icon('calendar')}</div><p class="small">Cada sesión cuenta. Descansar también.</p>${weekStrip()}<div class="week-bottom"><div class="row between"><span>Tu objetivo personal</span><strong>${st.days} / ${S.profile.goal} días</strong></div><div class="progress-line"><span style="width:${Math.min(100,st.days/S.profile.goal*100)}%"></span></div><button class="link-btn" data-action="plan">Ver y editar mi semana ${icon('arrow')}</button></div></section></div>${statCards()}
 <div class="section-heading"><div><h2>¿Cuánto tiempo tienes?</h2><p>La fuerza es a tu ritmo; los tiempos son orientativos.</p></div>${timeChoices()}</div>
 <div class="grid3 home-routines">${[ROUTINE.bike,ROUTINE.torso,ROUTINE.elliptical].map(routineCard).join('')}</div>
 <div class="section-heading"><div><h2>Cuida lo que viene después</h2><p>Pequeñas decisiones fuera del entrenamiento.</p></div><button class="link-btn" data-page="habits">Ver hábitos ${icon('arrow')}</button></div>
 <div class="tip-band"><div class="tip-icon">${icon('leaf','icon-lg')}</div><div><h3>No necesitas hacerlo perfecto.</h3><p>Muévete un poco, come de forma equilibrada y deja espacio para descansar.</p></div><button class="link-btn" data-action="article" data-id="balance">Leer consejo ${icon('arrow')}</button></div>`;}
function routinesHTML(){return pageHeader('Entrenar en casa','Encuentra tu sesión.','Elige fuerza, cardio o un día suave. Todas las rutinas se pueden adaptar.',`<button class="btn btn-light" data-action="plan">${icon('calendar')} Mi semana</button>`)+resumeBanner()+`<div class="row between wrap"><div class="filters">${[['all','Todas'],['strength','Fuerza'],['cardio','Cardio'],['mobility','Movilidad']].map(([id,n])=>`<button class="chip ${routineFilter===id?'selected':''}" data-action="routine-filter" data-id="${id}" aria-pressed="${routineFilter===id}">${n}</button>`).join('')}</div>${timeChoices()}</div><div class="grid3">${ROUTINES.filter(r=>routineFilter==='all'||r.kind===routineFilter).map(routineCard).join('')}</div><div class="notice mt">${icon('info')}<div><strong>Propuestas generales, no un plan clínico.</strong>Empieza por una vuelta si eres principiante. Deja un día completo entre sesiones exigentes del mismo grupo muscular y baja la dificultad siempre que lo necesites.${sourceLink('strength')}</div></div>`;}
function filteredExercises(){const q=query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return EXERCISES.filter(e=>(exerciseFilter==='all'||e.equipment===exerciseFilter)&&(!favOnly||S.favorites.includes(e.id))&&[e.name,e.muscles,EQUIPMENT[e.equipment],e.type].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));}
function catalogItems(){const list=filteredExercises();return list.length?`<div class="grid3">${list.map(exerciseCard).join('')}</div>`:empty('No hay ejercicios con esos filtros.','Prueba otro material o borra la búsqueda.',`<button class="btn btn-light" data-action="clear-filters">Limpiar filtros</button>`);}
function exercisesHTML(){return pageHeader('Biblioteca de movimientos','Primero, buena técnica.',`${EXERCISES.length} ejercicios con dos posiciones, explicación y una opción más sencilla.`)+`<div class="row between wrap"><label class="searchbox">${icon('search')}<input id="exercise-search" type="search" placeholder="Busca un ejercicio o una zona…" aria-label="Buscar ejercicios" value="${esc(query)}" autocomplete="off"></label><button class="chip ${favOnly?'selected':''}" data-action="favorites-only" aria-pressed="${favOnly}">${icon('star')} Favoritos</button></div><div class="filters" aria-label="Material">${Object.entries(EQUIPMENT).map(([id,n])=>`<button class="chip ${exerciseFilter===id?'selected':''}" data-action="exercise-filter" data-id="${id}" aria-pressed="${exerciseFilter===id}">${n}</button>`).join('')}</div><p class="small muted" style="margin:4px 0 16px" id="results-count" aria-live="polite">${filteredExercises().length} ejercicios · Toca una ficha para ver las posiciones ampliadas.</p><div class="library-visual-note"><strong>${Object.keys(EXERCISE_IMAGES).length} de ${EXERCISES.length} ejercicios con imágenes realistas.</strong> Las dos posiciones están incluidas en la app; los demás mantienen de momento los esquemas originales.</div><div id="catalog-items">${catalogItems()}</div><p class="app-footnote">Las imágenes de aspecto fotográfico están generadas con IA. No son fotografías de entrenadores ni un análisis de tu postura. Pueden contener imprecisiones: usa también las instrucciones y consulta a un profesional si tienes dudas.</p>`;}
function habitRows(){const h=S.habits[today()]||{};return HABITS.map(x=>`<button class="habit-item ${h[x.id]?'checked':''}" data-action="habit" data-id="${x.id}" aria-pressed="${!!h[x.id]}"><span class="habit-icon">${icon(x.icon)}</span><span class="habit-copy"><strong>${x.name}</strong><small>${x.desc}</small></span><span class="checkbox">${icon('check')}</span></button>`).join('');}
function habitsHTML(){const checked=HABITS.filter(x=>S.habits[today()]?.[x.id]).length;return pageHeader('Cuidarte también cuenta','Hábitos para sentirte mejor.','Alimentación, descanso y recuperación. Sin promesas mágicas ni dietas extremas.')+`<div class="grid2"><section class="card padded"><div class="row between"><h2>Mis pequeños hábitos de hoy</h2><span class="pill green">${checked} / 4</span></div><p class="small muted mt-sm">Un recordatorio amable, no un examen.</p>${habitRows()}</section><section class="card padded"><div class="eyebrow muted">Después del entrenamiento</div><h2 class="mt-sm">Termina cuidándote.</h2><div class="stack mt"><div class="notice">${icon('wind')}<div><strong>Baja el ritmo</strong>Muévete despacio hasta recuperar una respiración cómoda.</div></div><div class="notice">${icon('drop')}<div><strong>Agua y una comida normal</strong>Atiende a la sed y a tu siguiente comida. No necesitas un ritual complicado.</div></div><div class="notice">${icon('moon')}<div><strong>Haz espacio al descanso</strong>La siguiente sesión puede esperar si necesitas recuperarte.</div></div></div><button class="link-btn mt-sm" data-action="article" data-id="after">Ideas para después de entrenar ${icon('arrow')}</button></section></div><div class="section-heading"><div><h2>Recomendaciones con fundamento</h2><p>Consejos generales con enlaces a sus fuentes.</p></div></div><div class="grid3">${ARTICLES.map(a=>`<button class="card article" data-action="article" data-id="${a.id}"><span class="article-icon">${icon(a.icon)}</span><span class="eyebrow">${a.category}</span><h3>${a.title}</h3><p>${a.lead}</p><span class="link-btn">Leer recomendación ${icon('arrow')}</span></button>`).join('')}</div><div class="notice warning mt">${icon('shield')}<div><strong>La salud va primero.</strong>${SAFETY}<br><button class="link-btn" data-action="sources">Consultar fuentes y seguridad ${icon('arrow')}</button></div></div>`;}
function weightChart(){const arr=S.weights.slice(-16);if(arr.length<2)return `<p class="small muted mt">${arr.length?'Añade otra medición en una fecha diferente para ver la tendencia.':'El peso es opcional. Cuando registres dos mediciones, aparecerá la tendencia.'}</p>`;let min=Math.min(...arr.map(x=>x.kg)),max=Math.max(...arr.map(x=>x.kg)),span=Math.max(max-min,1);min-=span*.2;max+=span*.2;const days=arr.map(x=>parseDate(x.date).getTime()),daySpan=Math.max(1,days.at(-1)-days[0]);const pts=arr.map((w,i)=>[45+((days[i]-days[0])/daySpan)*485,160-(w.kg-min)/(max-min)*120]);let ylines=[0,1,2].map(i=>{let y=40+i*60;let value=max-(y-40)/120*(max-min);return `<path d="M45 ${y}H540" stroke="#E2E9DC"/><text x="35" y="${y+4}" text-anchor="end" font-size="10" fill="#71836E">${value.toFixed(1)}</text>`;}).join('');return `<svg class="chart" viewBox="0 0 570 197" role="img" aria-label="Evolución de ${arr[0].kg} a ${arr.at(-1).kg} kilogramos entre ${niceDate(arr[0].date)} y ${niceDate(arr.at(-1).date)}">${ylines}<path d="M${pts.map(p=>p.join(',')).join(' L')}" stroke="#376E55" stroke-width="2.5" fill="none"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#376E55"><title>${arr[i].date}: ${arr[i].kg} kg</title></circle>`).join('')}<text x="45" y="188" font-size="10" fill="#71836E">${niceDate(arr[0].date)}</text><text x="535" y="188" text-anchor="end" font-size="10" fill="#71836E">${niceDate(arr.at(-1).date)}</text></svg>`;}
function progressHTML(){const wk=weekDays(),vals=wk.map(k=>S.logs.filter(l=>l.date===k).reduce((a,b)=>a+b.minutes,0)),max=Math.max(30,...vals),last=S.weights.at(-1),first=S.weights[0],delta=last&&first?Math.round((last.kg-first.kg)*10)/10:0;return pageHeader('Lo que ya estás construyendo','Tu progreso, sin presión.','Registra lo que haces. El descanso y la regularidad también importan.',`<button class="btn btn-light" data-action="log">${icon('plus')} Añadir sesión</button>`)+statCards()+`<div class="grid2 mt"><section class="card padded"><div class="row between"><h2>Movimiento esta semana</h2><span class="small muted">Min de sesión</span></div><div class="bar-chart" role="img" aria-label="Minutos registrados de lunes a domingo: ${vals.join(', ')}">${vals.map((v,i)=>`<div class="bar-col ${wk[i]===today()?'today':''}"><b>${v||'–'}</b><div class="bar" style="height:${Math.max(3,v/max*100)}px"></div><span>${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'][i]}</span></div>`).join('')}</div><p class="small muted mt-sm">Incluye descansos de la sesión. El cardio moderado se registra por separado.</p><button class="link-btn mt-sm" data-action="plan">Editar mi semana ${icon('arrow')}</button></section><section class="card padded"><div class="row between"><h2>Peso · opcional</h2><button class="icon-btn" data-action="weight" aria-label="Añadir peso">${icon('plus')}</button></div>${last?`<div class="weight-stats"><div><strong>${last.kg.toLocaleString('es-ES')} <small style="display:inline;font-size:13px">kg</small></strong><small>${niceDate(last.date)}</small></div><div><strong>${delta>0?'+':''}${delta.toLocaleString('es-ES')}</strong><small>kg desde el primer registro</small></div></div>`:''}${weightChart()}${S.weights.length?'<button class="link-btn" data-action="weight-history">Ver y gestionar mediciones '+icon('arrow')+'</button>':''}</section></div><div class="section-heading"><div><h2>Tu historial</h2><p>${S.logs.length} sesiones registradas en este navegador.</p></div><button class="link-btn" data-action="export">${icon('download')} Copia de seguridad</button></div><section class="card padded">${S.logs.length?S.logs.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,60).map(l=>`<div class="history-row"><div class="history-icon">${icon(l.strength?'dumbbell':'activity')}</div><div><strong>${esc(l.title)}${l.partial?' · parcial':''}</strong><small>${niceDate(l.date)} · ${l.minutes} min de sesión · ${l.cardio} min de cardio moderado</small>${l.note?`<p class="small muted">${esc(l.note)}</p>`:''}</div><button class="icon-btn" data-action="edit-log" data-id="${esc(l.id)}" aria-label="Editar sesión del ${l.date}">${icon('edit')}</button><button class="icon-btn" data-action="delete-log" data-id="${esc(l.id)}" aria-label="Eliminar sesión del ${l.date}">${icon('trash')}</button></div>`).join(''):empty('Tu primera sesión tiene sitio aquí.','Puedes completar una rutina guiada o añadir una actividad que hayas hecho por tu cuenta.',`<button class="btn btn-primary" data-action="log">${icon('plus')} Registrar actividad</button>`)}</section>${S.logs.length>60?'<p class="small muted mt-sm">Se muestran las 60 sesiones más recientes. La copia de seguridad conserva todo el historial.</p>':''}<div class="notice mt">${icon('shield')}<div><strong>Tus datos se guardan aquí.</strong>No hay cuenta ni sincronización automática. Exporta una copia para conservarlos o llevarlos a otro dispositivo.</div></div>`;}
function render(focus=false){const scroll=window.scrollY;const title={home:'Hoy',routines:'Rutinas',exercises:'Ejercicios',habits:'Hábitos',progress:'Progreso'};$$('[data-page]').forEach(b=>{let active=b.dataset.page===page;b.classList.toggle('active',active);if(b.closest('nav')){if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}});$('#page').innerHTML=(!storageOK?`<div class="storage-alert">${icon('info')} ${esc(storageMessage)}</div>`:'')+({home:homeHTML,routines:routinesHTML,exercises:exercisesHTML,habits:habitsHTML,progress:progressHTML}[page])()+footer();$('#date-label').textContent=new Date().toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'});$('#avatar').textContent=(S.profile.name||'CA').slice(0,2).toUpperCase();updateStorageBadge();document.title=`${title[page]} · CASA ACTIVA`;if(focus){window.scrollTo({top:0,behavior:'instant'});$('#page-title')?.focus({preventScroll:true});}else window.scrollTo({top:scroll,behavior:'instant'});}
function navigate(dest){if(!['home','routines','exercises','habits','progress'].includes(dest))return;page=dest;try{history.replaceState(null,'','#'+dest);}catch{}render(true);}
function stopPose(){if(poseInterval){clearInterval(poseInterval);poseInterval=null;}}
function closeModal(){stopPose();$('#modal').close();modalMode='';}
function modal(title,body,eyebrow='Casa activa',actions=''){stopPose();const el=$('#modal');el.innerHTML=`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2 id="modal-title">${title}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-sticky">${actions}</div>`:''}`;if(!el.open)el.showModal();el.scrollTop=0;}
function openExercise(id){const e=EX[id];if(!e)return;if(S.active?.running)pausePlayer();modalMode='exercise';modal(''+e.name,`<div class="row wrap"><span class="pill">${EQUIPMENT[e.equipment]}</span><span class="pill">${e.type}</span><button class="link-btn" data-action="favorite-detail" data-id="${id}" aria-pressed="${S.favorites.includes(id)}">${icon('star')} ${S.favorites.includes(id)?'En favoritos':'Guardar favorito'}</button></div><p class="muted small mt-sm">${e.muscles}</p><div id="pose-view"><div class="pose-grid ${isLandscapeImage(id)?'landscape':''}">${[0,1].map(n=>`<figure class="pose"><button data-action="zoom" data-id="${id}" data-phase="${n}" aria-label="Ampliar posición ${n+1}">${scene(id,n,!hasRealisticImage(id))}</button><figcaption><span>${n+1}</span>${esc(phaseLabel(id,n))}</figcaption></figure>`).join('')}</div></div><div class="pose-tools"><p>${visualNote(id)}</p><button class="btn btn-light" data-action="animate" data-id="${id}" aria-pressed="false">${icon('repeat')} Alternar posiciones</button></div><div class="dose-grid"><div class="dose-box"><small>Dosis inicial orientativa</small><strong>${e.dose}</strong></div><div class="dose-box"><small>La prioridad</small><strong>${e.effort}</strong></div></div><p class="muted small mt-sm">${e.intro}</p><h3>Así se hace</h3><ol class="steps">${e.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="notice mt">${icon('wind')}<div><strong>Respira</strong>${e.breathing}</div></div><h3>Evita estos errores</h3><ul class="errors">${e.errors.map(s=>`<li>${s}</li>`).join('')}</ul><div class="notice warning">${icon('leaf')}<div><strong>Una opción más sencilla</strong>${e.easier}</div></div>${sourceLink(e.source,e.source==='row'?'Ver técnica y vídeo de remo':'Leer recomendaciones generales de referencia')}<p class="app-footnote">Las referencias generales no validan esta imagen ni prescriben una carga. La profundidad o los discos dibujados no son un objetivo que debas copiar. Si aparece dolor, para y adapta el ejercicio.</p>`,'Técnica · '+e.type,selectedRoutine?`<button class="btn btn-light btn-block" data-action="routine" data-id="${selectedRoutine}">${icon('arrow')} Volver a la rutina</button>`:'');}
function openRoutine(id){const r=ROUTINE[id];if(!r)return;selectedRoutine=id;modalMode='routine';const rd=roundsFor(r);modal(r.name,`<div class="row wrap"><span class="pill ${r.color}">${r.subtitle}</span><span class="pill">${r.equipment}</span></div><p class="muted small mt-sm">${r.desc}</p><form id="routine-form" data-routine="${id}"><div class="form-grid">${r.kind==='strength'?`<label class="field">Vueltas al circuito<select name="rounds" id="rounds-select">${[1,2,3].map(n=>`<option value="${n}" ${n===rd?'selected':''}>${n} ${n===1?'vuelta · para empezar':'vueltas'}</option>`).join('')}</select><span class="field-hint">Una serie de cada ejercicio por vuelta.</span></label><label class="field">Descanso entre series<select name="rest" id="routine-rest">${[30,45,60,90,120,180].map(n=>`<option value="${n}" ${n===S.profile.rest?'selected':''}>${n} segundos</option>`).join('')}</select><span class="field-hint">Puedes alargarlo o pausar en cualquier momento.</span></label>`:r.kind==='cardio'?`<label class="field">Duración total orientativa<select name="minutes">${[15,25,35].map(n=>`<option value="${n}" ${n===S.profile.minutes?'selected':''}>${n} minutos</option>`).join('')}</select></label><div class="dose-box"><small>Intensidad</small><strong>Suave a moderada; sin sprints.</strong></div>`:`<div class="dose-box"><small>Duración</small><strong>15 min suaves, con pausas a tu ritmo.</strong></div>`}</div><div class="notice mt-sm">${icon('info')}<div>${r.kind==='strength'?'Primero técnica: termina cada serie con margen para 2–3 repeticiones más. No tienes que usar los 5 kg si no los controlas. El cronómetro no obliga a seguir.':r.kind==='cardio'?'La sesión empieza con 5 minutos suaves y acaba con 3 minutos de vuelta a la calma. Ajusta el bloque central a tu capacidad.':'Movilidad cómoda y sin dolor. Un día de descanso completo también es una buena opción.'}</div></div><h3>Tu recorrido</h3><div class="sequence-row"><div class="thumb" style="display:grid;place-items:center;background:var(--soft)">${icon('activity','icon-lg')}</div><div class="sequence-copy"><strong>1. Calentamiento · 5 min</strong><small>Marcha suave y mueve las articulaciones; sin pesas.</small></div></div><div class="exercise-sequence">${r.ex.map(e=>`<button type="button" class="sequence-row" data-action="exercise" data-id="${e}"><div class="thumb">${scene(e,1,false)}</div><span class="sequence-copy"><strong>${EX[e].name}</strong><small>${r.kind==='cardio'?'Reparte el bloque central a un ritmo cómodo':EX[e].dose}</small></span>${icon('chevron')}</button>`).join('')}</div><div class="sequence-row"><div class="thumb" style="display:grid;place-items:center;background:var(--soft)">${icon('wind','icon-lg')}</div><div class="sequence-copy"><strong>Final. Vuelta a la calma · 3 min</strong><small>Reduce el ritmo de forma gradual. Estira después solo si te apetece.</small></div></div><label class="checkfield mt"><input type="checkbox" id="ready-check" required><span>He revisado los movimientos, tengo espacio seguro y adaptaré o pararé si algo molesta. <button type="button" class="link-btn" data-action="safety">Ver seguridad</button></span></label><p class="form-error" id="routine-error" role="alert"></p></form>`,'Prepara tu sesión',`<button class="btn btn-primary btn-block" data-action="start-routine" data-id="${id}">${icon('play')} Empezar la sesión guiada</button>`);}
function openArticle(id){const a=ARTICLES.find(x=>x.id===id);if(!a)return;modalMode='article';modal(a.title,`<div class="reading"><p class="lead">${a.lead}</p><p>${a.text}</p></div><div class="notice mt">${icon('leaf')}<div>Adapta las recomendaciones a tus necesidades. No sustituyen una evaluación médica ni un plan nutricional individual.</div></div>${sourceLink(a.source)}`,a.category);}
function openSources(){modalMode='sources';modal('Fuentes y seguridad',`<div class="notice warning">${icon('shield')}<div>${SAFETY}</div></div><h3>Cómo está pensada esta app</h3><p class="small muted">Las rutinas son propuestas generales elaboradas para este material, no rutinas publicadas o avaladas por las entidades citadas. Esta versión incorpora 9 ejercicios con dos ilustraciones realistas generadas con IA y conserva 9 con esquemas originales. Ninguna imagen está validada como evaluación de técnica; no se debe copiar la carga ni forzar el recorrido para igualarla. Los tiempos y repeticiones son un punto de partida, no una obligación. No se estiman calorías, diagnósticos ni resultados de pérdida de peso.</p><h3>Referencias de salud y entrenamiento</h3><div class="source-list">${Object.values(SOURCES).map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.name} ${icon('external')}</a>`).join('')}</div><p class="app-footnote">Fuentes consultadas: 23 de septiembre de 2026. Las páginas pueden cambiar. La consulta a enlaces externos requiere conexión.</p>`,'Información y uso responsable');}
function openPrivacy(){modalMode='privacy';modal('Tus datos se quedan en tu navegador',`<div class="reading"><p>La app no tiene servidor de usuarios, cuenta, anuncios ni analítica propia. No transmite tu nombre, peso, hábitos o sesiones.</p><p>El guardado usa <strong>localStorage</strong>, asociado al navegador y al origen de la página. No se sincroniza automáticamente entre móvil y ordenador. Otras personas que usen el mismo perfil del navegador podrían ver tus datos.</p><p>Al borrar datos de navegación o utilizar modo privado, puedes perder el historial. Instalar la app no crea una copia en la nube. Cambiar de dominio, navegador o ruta puede abrir un guardado diferente. Exporta una copia antes de trasladarla. Las copias de la versión anterior de CASA ACTIVA se pueden importar aquí.</p><p>El alojamiento en GitHub Pages registra información técnica de las visitas, como la dirección IP, conforme a su política. Eso es independiente del historial local: esta app no envía tu peso, hábitos, alias ni sesiones. No subas tus copias JSON al repositorio público. Los enlaces externos tienen sus propias políticas y necesitan conexión. El navegador puede liberar el contenido guardado sin conexión. Tu copia exportada contiene datos personales: guárdala en privado.</p></div><div class="row wrap mt"><button class="btn btn-primary" data-action="export">${icon('download')} Exportar copia</button><button class="btn btn-light" data-action="import">${icon('upload')} Importar copia</button></div>`,'Privacidad · Sin cuenta');}
function openPlan(){modalMode='plan';modal('Tu semana, a tu manera',`<p class="muted small">Plantilla orientativa, no recordatorios ni citas. Deja días de recuperación entre sesiones de fuerza exigentes. Guarda descanso donde lo necesites.</p><form id="plan-form"><div class="plan-grid mt">${['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'].map((n,i)=>`<label for="day-plan-${i}">${n.slice(0,3)}</label><select id="day-plan-${i}" name="day${i}" class="plan-select"><option value="rest" ${S.plan[i]==='rest'?'selected':''}>Descanso / paseo libre</option>${ROUTINES.map(r=>`<option value="${r.id}" ${S.plan[i]===r.id?'selected':''}>${r.name}</option>`).join('')}</select>`).join('')}</div><div class="notice warning mt">${icon('info')}<div id="plan-warning">Dos días de fuerza para los mismos músculos no deberían ser consecutivos. Esta plantilla no obliga a entrenar todos los días.</div></div><div class="modal-actions"><button type="button" class="btn btn-light" data-action="close-modal">Cancelar</button><button type="submit" class="btn btn-primary">${icon('check')} Guardar semana</button></div></form>`,'Planificación flexible');}
function openSettings(){modalMode='settings';modal('Un espacio a tu medida',`<form id="settings-form"><section class="settings-block"><h3>Tu perfil local</h3><div class="form-grid"><label class="field">Nombre o alias · opcional<input name="name" maxlength="40" value="${esc(S.profile.name)}" placeholder="¿Cómo te llamas?" autocomplete="off"></label><label class="field">Objetivo personal de actividad<select name="goal">${[1,2,3,4,5,6,7].map(n=>`<option value="${n}" ${n===S.profile.goal?'selected':''}>${n} ${n===1?'día':'días'} por semana</option>`).join('')}</select><span class="field-hint">Motivación personal, no prescripción médica.</span></label><label class="field">Tiempo habitual<select name="minutes">${[15,25,35].map(n=>`<option value="${n}" ${n===S.profile.minutes?'selected':''}>${n} min</option>`).join('')}</select></label><label class="field">Descanso inicial entre series<select name="rest">${[30,45,60,90,120,180].map(n=>`<option value="${n}" ${n===S.profile.rest?'selected':''}>${n} s</option>`).join('')}</select></label></div><label class="checkfield mt-sm"><input type="checkbox" name="sound" ${S.profile.sound?'checked':''}><span>Aviso sonoro al terminar un temporizador.<br><span class="field-hint">Depende del navegador y sus permisos. No son notificaciones en segundo plano.</span></span></label><div class="modal-actions"><button class="btn btn-primary" type="submit">${icon('check')} Guardar preferencias</button></div></section></form><section class="settings-block"><h3>Tu progreso</h3><p class="small muted">Se guarda en este navegador, sin sincronización en la nube. Exporta una copia antes de cambiar de dispositivo, de dirección web o de navegador.</p><div class="row wrap mt-sm"><button class="btn btn-light" data-action="export">${icon('download')} Exportar</button><button class="btn btn-light" data-action="import">${icon('upload')} Importar</button><button class="btn btn-light" data-action="privacy">${icon('shield')} Privacidad</button></div></section><section><h3>Empezar de nuevo</h3><p class="small muted">Elimina los datos de CASA ACTIVA de este navegador. No afecta a tus archivos de copia de seguridad.</p><button class="btn btn-danger mt-sm" data-action="reset">${icon('trash')} Borrar mis datos</button></section>`,'Preferencias');}

// Sesión guiada: nunca se avanza automáticamente a otro ejercicio.
let pendingImport=null,pendingStart=null,finishPartial=false,lastAutoSave=0;
function buildSteps(r,opts){
 const steps=[{kind:'warm',title:'Prepara el cuerpo',ex:'circles',secs:300,hint:'Marcha suavemente en el sitio y mueve hombros, codos y tobillos. Empieza muy suave; no uses pesas.',round:1}];
 if(r.kind==='strength'){
  const rounds=Math.round(num(opts.rounds,1,3,1)),rest=num(opts.rest,30,180,45);
  for(let round=1;round<=rounds;round++)for(let i=0;i<r.ex.length;i++){
   const id=r.ex[i],e=EX[id];
   steps.push({kind:'strength',title:e.name,ex:id,secs:id==='plank'?20:null,hint:id==='plank'?'Mantén 10–20 segundos solo si puedes respirar y controlar la postura. Puedes terminar antes.':`Una serie a tu ritmo. ${e.dose.replace(/^1–2 series de /, "")} Deja margen; no hace falta llegar al límite.`,round});
   if(round<rounds||i<r.ex.length-1)steps.push({kind:'rest',title:'Recupera el aliento',ex:null,secs:rest,hint:'Respira con calma. Prepara el siguiente ejercicio sin prisas y amplía el descanso si lo necesitas.',round});
  }
 }else if(r.kind==='cardio'){
  const seconds=num(opts.minutes,15,35,25)*60-480,each=Math.floor(seconds/r.ex.length);
  r.ex.forEach((id,i)=>steps.push({kind:'cardio',title:EX[id].name,ex:id,secs:each+(i===r.ex.length-1?seconds-each*r.ex.length:0),hint:'Ritmo cómodo, suave a moderado. En intensidad moderada puedes hablar, pero no cantar. Baja el ritmo si lo necesitas.',round:1}));
 }else{
  r.ex.forEach((id,i)=>{steps.push({kind:'mobility',title:EX[id].name,ex:id,secs:60,hint:'Haz unas pocas repeticiones lentas y cómodas. Puedes detenerte y descansar antes de que termine el minuto.',round:1});if(i<r.ex.length-1)steps.push({kind:'rest',title:'Una pausa tranquila',ex:null,secs:60,hint:'Respira sin forzar y prepara la siguiente posición.',round:1});});
 }
 steps.push({kind:'cool',title:'Baja el ritmo, poco a poco',ex:null,secs:180,hint:'Camina o mueve las piernas suavemente y reduce el esfuerzo gradualmente. Alarga la calma si lo necesitas; no fuerces estiramientos.',round:1});return steps;
}
function startRoutine(id){const form=$('#routine-form');if(!form||!ROUTINE[id])return;if(!$('#ready-check').checked){$('#routine-error').textContent='Revisa los movimientos y marca la casilla de seguridad para comenzar.';$('#ready-check').focus();return;}const f=new FormData(form),opts={rounds:f.get('rounds')||1,rest:f.get('rest')||S.profile.rest,minutes:f.get('minutes')||15};
 if(S.active){pendingStart={id,opts};modal('Ya hay una sesión en curso',`<p class="small">Puedes continuarla o descartarla antes de empezar otra. Descartar no elimina tus sesiones ya guardadas.</p><div class="modal-actions"><button class="btn btn-light" data-action="resume">Continuar anterior</button><button class="btn btn-danger" data-action="replace-active">Descartar y empezar</button></div>`,'Sesión pendiente');return;}beginSession(id,opts);
}
function beginSession(id,opts){pausePlayer();S.active={id:uid(),routine:id,steps:buildSteps(ROUTINE[id],opts),index:0,elapsed:0,total:0,cardio:0,done:[],skipped:[],running:false,last:null,date:today()};pendingStart=null;save();closeModal();render();openPlayer();}
function formatTime(ms){const s=Math.max(0,Math.ceil(ms/1000)),h=Math.floor(s/3600);return h?`${h}:${String(Math.floor(s/60)%60).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`:`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function currentStep(){return S.active?.steps[S.active.index];}
function initAudio(){if(!S.profile.sound)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});}catch{}}
function beep(){if(!S.profile.sound||!audioCtx||audioCtx.state!=='running')return;try{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.frequency.value=660;g.gain.setValueAtTime(.05,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.3);o.start();o.stop(audioCtx.currentTime+.32);}catch{}}
function tick(){const a=S.active;if(!a?.running)return;const now=Date.now(),st=currentStep();let delta=Math.max(0,now-(a.last||now));a.last=now;if(st.secs!==null)delta=Math.min(delta,Math.max(0,st.secs*1000-a.elapsed));a.elapsed+=delta;a.total+=delta;if(st.kind==='cardio')a.cardio+=delta;
 if(st.secs!==null&&a.elapsed>=st.secs*1000){a.running=false;a.last=null;beep();save();renderPlayer();toast('Bloque terminado. Continúa cuando estés preparado.');}else updateClock();
 if(now-lastAutoSave>5000){lastAutoSave=now;save();}
}
function pausePlayer(){if(S.active?.running){tick();if(S.active){S.active.running=false;S.active.last=null;save();}}updateClock();}
function togglePlayer(){if(!S.active)return;const a=S.active,st=currentStep();if(a.running)pausePlayer();else{if(st.secs!==null&&a.elapsed>=st.secs*1000)return;initAudio();a.running=true;a.last=Date.now();save();}renderPlayer();}
function openPlayer(){if(!S.active)return;closeModal();renderPlayer();if(!$('#player').open)$('#player').showModal();}
function renderPlayer(){const a=S.active;if(!a)return;const st=currentStep(),finished=st.secs!==null&&a.elapsed>=st.secs*1000,kind={warm:'Calentamiento',cool:'Vuelta a la calma',rest:'Descanso',strength:`Fuerza · Vuelta ${st.round}`,cardio:'Cardio',mobility:'Movilidad'}[st.kind];
 const next=a.steps[a.index+1];$('#player').innerHTML=`<div class="modal-head"><div><div class="eyebrow">${esc(ROUTINE[a.routine].name)}</div><h2 id="player-title">Paso ${a.index+1} de ${a.steps.length}</h2></div><button class="icon-btn" data-action="leave-player" aria-label="Pausar y cerrar sesión guiada">${icon('close')}</button></div><div class="progress-line" style="border-radius:0;height:4px"><span style="width:${a.index/a.steps.length*100}%"></span></div><div class="player-layout"><div class="player-visual">${st.ex?scene(st.ex,1,true):`<div class="rest-visual"><div class="rest-ring">${icon(st.kind==='cool'?'leaf':'wind')}</div></div>`}${st.ex?`<button class="link-btn" data-action="exercise" data-id="${st.ex}">${icon('book')} Ver técnica antes de seguir</button>`:''}</div><div class="player-stage"><span class="pill">${kind}</span><h2>${esc(st.title)}</h2><p>${esc(st.hint)}</p><div class="timer-digits" id="timer-digits" aria-label="Tiempo del bloque">${formatTime(st.secs===null?a.elapsed:st.secs*1000-a.elapsed)}</div><div class="timer-label" id="timer-label">${finished?'Bloque terminado · avanza cuando estés listo':a.running?(st.secs===null?'Cuenta tu serie a tu ritmo':'En marcha'):'En pausa · pulsa iniciar'}</div><div class="player-actions"><button class="btn btn-primary" data-action="toggle-player" ${finished?'disabled':''}>${icon(a.running?'pause':'play')} ${a.running?'Pausar':'Iniciar'}</button><button class="btn btn-light" data-action="next-step">${icon('check')} ${st.kind==='strength'?'Serie hecha':'Terminar bloque'}</button></div>${st.kind==='rest'?'<div class="row mt-sm"><button class="chip" data-action="add-rest" data-id="15">+15 s</button><button class="chip" data-action="add-rest" data-id="30">+30 s</button></div>':''}</div></div><div class="player-meta"><div class="notice">${icon('info')}<div>${st.kind==='strength'?'Las repeticiones las cuentas tú. El tiempo no mide la calidad de tu técnica.':'El temporizador no avanza solo al siguiente bloque.'} Puedes terminar antes o saltar lo que no sea adecuado.</div></div><p class="small muted mt-sm">${next?`Después: <strong>${esc(next.title)}</strong>`:'Último bloque. Después podrás revisar y guardar tu sesión.'}</p></div><div class="player-footer"><span class="player-total">Tiempo activo de sesión: <strong id="player-total">${formatTime(a.total)}</strong></span><div class="row wrap"><button class="btn btn-light" data-action="skip-step">Saltar</button><button class="btn btn-light" data-action="finish-early">Finalizar sesión</button></div></div>`;
}
function updateClock(){const a=S.active,st=currentStep();if(!a||!st)return;const el=$('#timer-digits');if(el)el.textContent=formatTime(st.secs===null?a.elapsed:st.secs*1000-a.elapsed);const total=$('#player-total');if(total)total.textContent=formatTime(a.total);}
function nextStep(skip=false){if(!S.active)return;pausePlayer();const a=S.active;if(skip){if(!a.skipped.includes(a.index))a.skipped.push(a.index);}else if(!a.done.includes(a.index))a.done.push(a.index);
 if(a.index===a.steps.length-1){save();openFinish(skip);return;}a.index++;a.elapsed=0;a.last=null;save();renderPlayer();}
function leavePlayer(){pausePlayer();$('#player').close();render();}
function openFinish(partial=false){if(!S.active)return;pausePlayer();const a=S.active;finishPartial=partial||a.skipped.some(i=>['strength','cardio','mobility'].includes(a.steps[i].kind))||a.steps.some((st,i)=>['strength','cardio','mobility'].includes(st.kind)&&!a.done.includes(i));const minutes=Math.round(a.total/60000),cardio=Math.min(minutes,Math.floor(a.cardio/60000));modalMode='finish';modal('Lo que has hecho cuenta.',`<p class="small muted">Revisa los datos antes de guardarlos. El tiempo medido incluye los bloques iniciados y los descansos con cronómetro, pero no las pausas.</p><div class="notice mt-sm">${icon('check')}<div><strong>${finishPartial?'Sesión parcial':'Recorrido terminado'}</strong>${a.done.filter(i=>['strength','cardio','mobility'].includes(a.steps[i].kind)).length} bloques de ejercicio marcados como hechos. No se guarda nada hasta confirmar.</div></div><form id="finish-form"><div class="form-grid mt"><label class="field">Tiempo real de la sesión · min<input type="number" name="minutes" min="1" max="600" step="1" required value="${minutes||''}" placeholder="Minutos realizados"></label><label class="field">De ellos, cardio moderado · min<input type="number" name="cardio" min="0" max="600" step="1" required value="${cardio}"><span class="field-hint">Pon 0 si fue suave. No cuentes aquí descansos o fuerza.</span></label><label class="field">Esfuerzo percibido<select name="effort">${effortOptions(5)}</select></label><label class="field">Fecha<input type="date" name="date" required max="${today()}" value="${a.date<=today()?a.date:today()}"></label><label class="field wide">Una nota · opcional<textarea name="note" maxlength="500" placeholder="¿Cómo te has sentido?"></textarea></label></div><p class="form-error" id="finish-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn btn-light" data-action="resume">Volver</button><button class="btn btn-primary" type="submit">${icon('check')} Guardar sesión</button></div></form><button class="link-btn mt-sm" data-action="discard-active">Descartar sin guardar</button>`,'Tu entrenamiento');}
function effortOptions(current=5){return Array.from({length:10},(_,i)=>`<option value="${i+1}" ${i+1===current?'selected':''}>${i+1} / 10${i===0?' · muy suave':i===4?' · moderado':i===9?' · máximo (no es el objetivo)':''}</option>`).join('');}
function openLog(id=null){const l=S.logs.find(x=>x.id===id)||{date:today(),title:'Entrenamiento libre',minutes:'',cardio:0,strength:false,effort:5,note:''};modalMode='log';modal(id?'Editar sesión':'Apunta tu actividad',`<p class="small muted">Puedes registrar una sesión fuera de la app, un paseo o corregir sus minutos. Los datos son introducidos por ti, no medidos por un sensor.</p><form id="log-form" data-id="${esc(id||'')}"><div class="form-grid mt"><label class="field wide">Actividad<input name="title" maxlength="100" required value="${esc(l.title)}"></label><label class="field">Fecha<input name="date" type="date" required max="${today()}" value="${l.date}"></label><label class="field">Tiempo real · minutos<input name="minutes" type="number" min="1" max="600" step="1" required value="${l.minutes}"></label><label class="field">Cardio moderado · minutos<input name="cardio" type="number" min="0" max="600" step="1" required value="${l.cardio}"><span class="field-hint">Dentro del total. Excluye cardio suave, fuerza y descansos.</span></label><label class="field">Esfuerzo percibido<select name="effort">${effortOptions(l.effort)}</select></label><label class="checkfield wide"><input type="checkbox" name="strength" ${l.strength?'checked':''}><span>He realizado ejercicios de fuerza.</span></label><label class="field wide">Una nota · opcional<textarea name="note" maxlength="500">${esc(l.note)}</textarea></label></div><p class="form-error" id="log-error" role="alert"></p><div class="modal-actions"><button class="btn btn-light" type="button" data-action="close-modal">Cancelar</button><button class="btn btn-primary" type="submit">${icon('check')} Guardar</button></div></form>`,'Tu progreso');}
function openWeight(){modalMode='weight';const existing=S.weights.find(w=>w.date===today());modal('El peso es solo un dato',`<p class="small muted">Registrar el peso es opcional. La energía, la fuerza y la constancia también importan. Una entrada en la misma fecha reemplaza la anterior.</p><form id="weight-form"><div class="form-grid mt"><label class="field">Fecha<input type="date" name="date" required max="${today()}" value="${today()}"></label><label class="field">Peso · kg<input type="number" name="kg" step="0.1" min="25" max="350" inputmode="decimal" required placeholder="Ej. 78,5" value="${existing?.kg||''}"></label></div><p class="form-error" id="weight-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn btn-light" data-action="close-modal">Cancelar</button><button type="submit" class="btn btn-primary">${icon('check')} Guardar peso</button></div></form>`,'Registro opcional');}
function weightHistory(){modalMode='weights';modal('Tus registros de peso',S.weights.length?`<div class="log-list">${S.weights.slice().reverse().map(w=>`<div class="log-row"><div><strong>${w.kg.toLocaleString('es-ES')} kg</strong><p class="small muted">${niceDate(w.date,{day:'numeric',month:'long',year:'numeric'})}</p></div><button class="icon-btn" data-action="delete-weight" data-id="${w.date}" aria-label="Borrar peso del ${w.date}">${icon('trash')}</button></div>`).join('')}</div>`:empty('Aún no hay registros.','No es necesario pesarte para usar esta app.'),'Registro opcional');}
function confirmation(title,text,action,id=''){modalMode='confirm';modal(title,`<p class="small">${text}</p><div class="modal-actions"><button class="btn btn-light" data-action="close-modal">Cancelar</button><button class="btn btn-danger" data-action="${action}" data-id="${esc(id)}">Confirmar</button></div>`,'Confirmación');}
function snapshot(){pausePlayer();const d=JSON.parse(JSON.stringify(S));if(d.active){d.active.running=false;d.active.last=null;}return JSON.stringify(d,null,2);}
function openExport(){modalMode='export';modal('Una copia de tu progreso',`<p class="small muted">Contiene tu perfil, favoritos, semana, hábitos, sesiones, peso y la sesión pendiente. Guárdala en privado. Sirve para trasladar todos los datos a otro navegador, no para sincronizarlos.</p><div class="row wrap mt"><button class="btn btn-primary" data-action="download-backup">${icon('download')} Descargar JSON</button><button class="btn btn-light" data-action="copy-backup">Copiar texto</button></div><label class="field mt">Copia manual · si Sites bloquea la descarga<textarea class="backup-text" id="backup-text" rows="9" readonly>${esc(snapshot())}</textarea></label><p class="field-hint">También puedes seleccionar todo el texto, copiarlo y usar «Importar» en otro dispositivo.</p>`,'Copia de seguridad');}
function downloadBackup(){const text=$('#backup-text')?.value||snapshot(),url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`casa-activa-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Descarga solicitada. Si no aparece, usa la copia manual.');}
function openImport(){pendingImport=null;modalMode='import';modal('Recupera una copia',`<p class="small muted">Importar reemplazará los datos de este navegador tras una confirmación. No fusiona registros; exporta antes la versión que quieras conservar.</p><label class="field mt">Selecciona tu archivo JSON<input id="import-file" type="file" accept=".json,application/json"></label><label class="field mt">O pega el texto de una copia<textarea id="import-text" rows="8" maxlength="3000000" placeholder="Pega aquí el contenido JSON"></textarea></label><p class="form-error" id="import-error" role="alert"></p><div class="modal-actions"><button class="btn btn-light" data-action="close-modal">Cancelar</button><button class="btn btn-primary" data-action="parse-import">Revisar copia</button></div>`,'Copia de seguridad');}
function parseImport(){try{const text=$('#import-text').value.trim();if(!text)throw Error('Selecciona un archivo o pega el texto de una copia.');if(text.length>3000000)throw Error('El archivo supera el límite de 3 MB.');pendingImport=sanitize(JSON.parse(text));modalMode='import-confirm';modal('¿Reemplazar tus datos?',`<p class="small">La copia contiene <strong>${pendingImport.logs.length} sesiones</strong>, <strong>${pendingImport.weights.length} registros de peso</strong> y <strong>${pendingImport.favorites.length} favoritos</strong>.</p><div class="notice warning mt">${icon('info')}<div>Se sustituirán los datos actuales de CASA ACTIVA en este navegador. Una sesión pendiente se recuperará en pausa.</div></div><div class="modal-actions"><button class="btn btn-light" data-action="close-modal">Cancelar</button><button class="btn btn-primary" data-action="confirm-import">Reemplazar datos</button></div>`,'Última comprobación');}catch(e){$('#import-error').textContent=e instanceof SyntaxError?'El texto no es un JSON válido. Selecciona una copia exportada desde esta app.':e.message;}}
function openReset(){modalMode='reset';modal('Borrar los datos de esta app',`<p class="small muted">Se eliminarán todas las sesiones, pesos, hábitos, favoritos y preferencias locales. Tus archivos exportados no se borran.</p><label class="field mt">Escribe BORRAR para confirmar<input id="reset-text" autocomplete="off" placeholder="BORRAR"></label><div class="modal-actions"><button class="btn btn-light" data-action="close-modal">Cancelar</button><button class="btn btn-danger" data-action="confirm-reset">${icon('trash')} Borrar definitivamente</button></div>`,'Acción irreversible en este navegador');}
function openZoom(id,phase){const z=$('#zoom');z.innerHTML=`<div class="modal-head"><h2 id="zoom-title">${esc(EX[id].name)}</h2><button class="icon-btn" data-action="close-zoom" aria-label="Cerrar imagen ampliada">${icon('close')}</button></div><div class="zoom-image">${scene(id,phase,true)}</div><p class="small muted" style="padding:0 20px 20px">${visualNote(id)}</p>`;z.showModal();}
function toggleAnimation(id,button){const box=$('#pose-view');if(!box)return;if(poseInterval){stopPose();openExercise(id);return;}let p=0;const paint=()=>{box.innerHTML=`<figure class="pose wide"><button data-action="zoom" data-id="${id}" data-phase="${p}" aria-label="Ampliar posición ${p+1}">${scene(id,p,!hasRealisticImage(id))}</button><figcaption><span>${p+1}</span> ${p?'Segunda posición':'Primera posición'} · alternancia orientativa</figcaption></figure>`;p=1-p;};paint();poseInterval=setInterval(paint,1700);button.innerHTML=`${icon('pause')} Ver posiciones fijas`;button.setAttribute('aria-pressed','true');}
function readSessionForm(f,errorID){const date=f.get('date'),minutes=Number(f.get('minutes')),cardio=Number(f.get('cardio'));let error='';if(!validDate(date)||date>today())error='Introduce una fecha válida, no posterior a hoy.';else if(!Number.isFinite(minutes)||minutes<1||minutes>600)error='El tiempo de sesión debe estar entre 1 y 600 minutos.';else if(!Number.isFinite(cardio)||cardio<0||cardio>minutes)error='El cardio moderado no puede superar el tiempo total de sesión.';if(error){$(errorID).textContent=error;return null;}return {date,minutes:Math.round(minutes),cardio:Math.round(cardio),effort:Math.round(num(f.get('effort'),1,10,5)),note:String(f.get('note')||'').slice(0,500)};}

// Delegación de eventos; app estática sin dependencias externas.
document.addEventListener('click',async ev=>{
 const nav=ev.target.closest('[data-page]');if(nav){navigate(nav.dataset.page);return;}
 const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
 try{switch(a){
 case 'minutes': S.profile.minutes=+[15,25,35].find(n=>n===+id)||25;save();render();break;
 case 'routine-filter':routineFilter=id;render();break;
 case 'exercise-filter':exerciseFilter=id;render();break;
 case 'clear-filters':exerciseFilter='all';query='';favOnly=false;render();break;
 case 'favorites-only':favOnly=!favOnly;render();break;
 case 'favorite':case 'favorite-detail':if(!Object.hasOwn(EX,id))break;S.favorites=S.favorites.includes(id)?S.favorites.filter(x=>x!==id):[...S.favorites,id];save();render();if(a==='favorite-detail')openExercise(id);else toast(S.favorites.includes(id)?'Ejercicio guardado en favoritos.':'Ejercicio quitado de favoritos.');break;
 case 'routine':openRoutine(id);break;
 case 'exercise':if(!b.closest('#modal')||modalMode!=='routine')selectedRoutine=null;openExercise(id);break;
 case 'zoom':openZoom(id,+b.dataset.phase||0);break;
 case 'close-zoom':$('#zoom').close();break;
 case 'animate':toggleAnimation(id,b);break;
 case 'article':openArticle(id);break;
 case 'sources':openSources();break;
 case 'safety':modal('Antes de empezar',`<div class="notice warning">${icon('shield')}<div>${SAFETY}</div></div><p class="small muted mt">Ten agua cerca, retira obstáculos y comprueba que el equipo está estable. No estrenes un movimiento difícil con carga. La app no comprueba tu aptitud médica ni observa tu técnica.</p>`,'Entrena con cuidado',selectedRoutine?`<button class="btn btn-primary btn-block" data-action="routine" data-id="${selectedRoutine}">Volver a preparar la rutina</button>`:'');break;
 case 'privacy':openPrivacy();break;
 case 'settings':openSettings();break;
 case 'plan':openPlan();break;
 case 'habit':if(!HABITS.some(h=>h.id===id))break;if(!S.habits[today()])S.habits[today()]={};S.habits[today()][id]=!S.habits[today()][id];save();render();break;
 case 'close-modal':closeModal();break;
 case 'start-routine':startRoutine(id);break;
 case 'replace-active':if(pendingStart){const p=pendingStart;beginSession(p.id,p.opts);}break;
 case 'resume':openPlayer();break;
 case 'toggle-player':togglePlayer();break;
 case 'next-step':nextStep();break;
 case 'skip-step':nextStep(true);break;
 case 'add-rest':if(S.active&&currentStep().kind==='rest'){tick();currentStep().secs=Math.min(1800,currentStep().secs+(+id===30?30:15));save();renderPlayer();}break;
 case 'leave-player':leavePlayer();break;
 case 'finish-early':openFinish(true);break;
 case 'discard-active':confirmation('¿Descartar esta sesión?','No se añadirá nada al historial. Los entrenamientos anteriores se conservan.','confirm-discard');break;
 case 'confirm-discard':pausePlayer();S.active=null;save();closeModal();$('#player').close();render();toast('Sesión descartada.');break;
 case 'log':openLog();break;
 case 'edit-log':openLog(id);break;
 case 'delete-log':confirmation('¿Eliminar esta sesión?','Se eliminará solo este registro de actividad.','remove-log',id);break;
 case 'remove-log':S.logs=S.logs.filter(l=>l.id!==id);save();closeModal();render();toast('Registro eliminado.');break;
 case 'weight':openWeight();break;
 case 'weight-history':weightHistory();break;
 case 'delete-weight':confirmation('¿Eliminar este peso?',`Se borrará la medición del ${niceDate(id)}.`,'remove-weight',id);break;
 case 'remove-weight':S.weights=S.weights.filter(w=>w.date!==id);save();render();weightHistory();break;
 case 'export':openExport();break;
 case 'download-backup':downloadBackup();break;
 case 'copy-backup':{const t=$('#backup-text');t.focus();t.select();try{await navigator.clipboard.writeText(t.value);toast('Copia de seguridad copiada.');}catch{let ok=false;try{ok=document.execCommand('copy');}catch{}toast(ok?'Copia de seguridad copiada.':'Texto seleccionado. Usa Copiar en el menú del dispositivo.');}break;}
 case 'import':openImport();break;
 case 'parse-import':parseImport();break;
 case 'confirm-import':if(pendingImport){pausePlayer();S=pendingImport;pendingImport=null;try{localStorage.setItem(STORE+'_test','1');localStorage.removeItem(STORE+'_test');storageOK=true;storageMessage='';}catch{}save();closeModal();$('#player').close();render();toast(storageOK?'Copia importada.':'Copia cargada solo en memoria. Exporta antes de salir.');}break;
 case 'reset':openReset();break;
 case 'confirm-reset':if($('#reset-text').value!=='BORRAR'){toast('Escribe BORRAR exactamente para confirmar.');break;}pausePlayer();try{localStorage.removeItem(STORE);localStorage.setItem(STORE+'_test','1');localStorage.removeItem(STORE+'_test');storageOK=true;storageMessage='';}catch{}S=initial();save();closeModal();$('#player').close();page='home';render(true);toast('Se han borrado los datos de CASA ACTIVA.');break;
 }}catch(err){console.error('CASA ACTIVA:',err);toast('No se pudo completar la acción. Conserva una copia de tus datos.');}
});
document.addEventListener('input',ev=>{if(ev.target.id==='exercise-search'){query=ev.target.value;$('#catalog-items').innerHTML=catalogItems();$('#results-count').textContent=`${filteredExercises().length} ejercicios · Toca una ficha para ver las posiciones.`;}});
document.addEventListener('change',async ev=>{if(ev.target.id==='import-file'){const f=ev.target.files?.[0];if(!f)return;try{if(f.size>3000000)throw Error('El archivo supera el límite de 3 MB.');const text=await f.text();if($('#import-text'))$('#import-text').value=text;if($('#import-error'))$('#import-error').textContent='Archivo cargado. Pulsa «Revisar copia».';}catch(e){if($('#import-error'))$('#import-error').textContent=e.message;}}});
document.addEventListener('submit',ev=>{
 const form=ev.target;if(!['settings-form','plan-form','log-form','weight-form','finish-form','routine-form'].includes(form.id))return;ev.preventDefault();const f=new FormData(form);
 if(form.id==='routine-form'){startRoutine(form.dataset.routine);return;}
 if(form.id==='settings-form'){S.profile={name:String(f.get('name')||'').trim().slice(0,40),goal:Math.round(num(f.get('goal'),1,7,3)),minutes:[15,25,35].includes(+f.get('minutes'))?+f.get('minutes'):25,rest:num(f.get('rest'),30,180,45),sound:f.get('sound')==='on'};save();closeModal();render();toast(storageOK?'Preferencias guardadas.':'Preferencias aplicadas sin guardado persistente.');return;}
 if(form.id==='plan-form'){S.plan=Array.from({length:7},(_,i)=>{const v=f.get('day'+i);return v==='rest'||Object.hasOwn(ROUTINE,v)?v:'rest';});save();closeModal();render();const adjacent=S.plan.some((r,i)=>ROUTINE[r]?.kind==='strength'&&ROUTINE[S.plan[(i+1)%7]]?.kind==='strength');toast(adjacent?'Semana guardada. Revisa la recuperación entre días de fuerza consecutivos.':'Semana guardada. Puedes adaptarla cada día.');return;}
 if(form.id==='weight-form'){const date=f.get('date'),kg=Number(f.get('kg'));if(!validDate(date)||date>today()||!Number.isFinite(kg)||kg<25||kg>350){$('#weight-error').textContent='Revisa la fecha y el peso introducidos.';return;}S.weights=S.weights.filter(w=>w.date!==date);S.weights.push({date,kg:Math.round(kg*10)/10});S.weights.sort((a,b)=>a.date.localeCompare(b.date));save();closeModal();render();toast('Peso registrado.');return;}
 if(form.id==='log-form'){const details=readSessionForm(f,'#log-error');if(!details)return;const title=String(f.get('title')||'').trim().slice(0,100);if(!title){$('#log-error').textContent='Escribe el nombre de la actividad.';return;}const old=S.logs.find(l=>l.id===form.dataset.id),log={id:old?.id||uid(),title,...details,strength:f.get('strength')==='on',partial:old?.partial||false};S.logs=S.logs.filter(l=>l.id!==log.id);S.logs.push(log);save();closeModal();render();toast('Sesión guardada.');return;}
 if(form.id==='finish-form'){if(!S.active)return;const details=readSessionForm(f,'#finish-error');if(!details)return;const a=S.active;if(S.logs.some(l=>l.id===a.id)){toast('Esta sesión ya está guardada.');return;}S.logs.push({id:a.id,title:ROUTINE[a.routine].name,...details,strength:a.done.some(i=>a.steps[i].kind==='strength'),partial:finishPartial});S.active=null;save();closeModal();$('#player').close();page='progress';render(true);toast('Sesión guardada. Ahora toca recuperar.');return;}
});
$('#modal').addEventListener('cancel',()=>{stopPose();modalMode='';});
$('#modal').addEventListener('close',()=>{stopPose();if($('#player').open&&S.active)renderPlayer();});
$('#player').addEventListener('cancel',()=>{pausePlayer();render();});
window.addEventListener('pagehide',()=>{pausePlayer();save();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){tick();if($('#player').open)renderPlayer();}else save();});
const NAV=[['home','home','Hoy'],['routines','dumbbell','Rutinas'],['exercises','grid','Ejercicios'],['habits','heart','Hábitos'],['progress','chart','Progreso']];
$('#side-nav').innerHTML=NAV.map(([id,i,n])=>`<button class="nav-btn" data-page="${id}">${icon(i)}${n}</button>`).join('');
$('#bottom-nav').innerHTML=NAV.map(([id,i,n])=>`<button data-page="${id}">${icon(i)}<span>${n}</span></button>`).join('');
$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
// Small integration surface. The PWA never serializes or uploads personal data.
window.CasaApp=Object.freeze({
 hasActiveSession:()=>Boolean(S.active),
 prepareForReload:()=>{pausePlayer();return save();},
 notify:message=>toast(message)
});
const initialRoute=location.hash.slice(1);
if(['home','routines','exercises','habits','progress'].includes(initialRoute))page=initialRoute;
window.addEventListener('hashchange',()=>{
 const target=location.hash.slice(1);
 if(['home','routines','exercises','habits','progress'].includes(target))navigate(target);
});
render();
clockInterval=setInterval(()=>{tick();if(lastDay!==today()&&!$('dialog[open]')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){lastDay=today();render();}},250);
